// 类式插件的惯用写法：`this.ctx.<svc>.<method>()`。
//
// 背景：主规则的 lookbehind `(?<![\w$.])` 挡住了 `myctx.` 这类前缀（对的），
// 但它**顺带也挡住了 `this.ctx.`** —— 因为 `ctx` 前面是 `.`。
// 实测 desktop profile 上这个形态出现 **32 次**，涉及 4 个服务，全部不可见；
// 其中 `dsh-mnemon` 的 `this.ctx.agents.get(...)` 让它被判成
// 「agents 没有任何调用点」，也就是把一个真调用报成了"没用到"。
//
// 这里调用 `tools.register` —— 它在 fixture 运行时面里**存在**，
// 所以只要这个调用被认出来，结论就还是 ok（不产生发现）。
// 但它必须出现在 callSites 里，否则这条夹具没有测到东西。
export function apply(ctx) {
  return {
    run() {
      this.ctx.tools.register({ name: 'thisctx' })
    },
  }
}
